  "rationale": "The incumbent appears locally saturated under amplitude optimization, while finer combs have previously produced larger gains. This search creates new internal gaps by borrowing space from adjacent empty intervals, preserving packet values and avoiding global resampling.",
  "source": "import time
import numpy as np
from scipy.signal import oaconvolve

PARAMS = {
    "time_fraction": (0.70, 0.30, 0.75),
    "max_packet_mass": (0.04, 0.001, 0.20),
    "minimum_width": (4, 2, 128),
    "trials": (100, 10, 500),
}


def exact_score(f):
    f = np.maximum(np.asarray(f, dtype=np.float64), 0.0)
    c = oaconvolve(f, f, mode="full")
    x = np.linspace(-0.5, 0.5, len(c) + 2)
    dx = np.diff(x)
    y = np.concatenate(([0.0], c, [0.0]))
    y1, y2 = y[:-1], y[1:]
    numerator = float(np.sum((dx / 3.0) * (y1**2 + y1*y2 + y2**2)))
    norm1 = np.sum(np.abs(c)) / (len(c) + 1)
    return float(numerator / (norm1 * np.max(np.abs(c))))


def construct(params, seed, budget_s, init=None):
    started = time.monotonic()
    deadline = started + float(params["time_fraction"]) * budget_s
    if init is None:
        return {"values": [1.0]}
    f = np.maximum(np.asarray(init["values"], dtype=np.float64), 0.0)
    best_score = exact_score(f)
    best_result = init
    n = len(f)
    mask = f > 0.0
    changes = np.diff(np.concatenate(([False], mask, [False])).astype(np.int8))
    starts = np.flatnonzero(changes == 1)
    ends = np.flatnonzero(changes == -1)
    if len(starts) < 2 or time.monotonic() >= deadline:
        return best_result
    prefix = np.concatenate(([0.0], np.cumsum(f)))
    masses = prefix[ends] - prefix[starts]
    total_mass = prefix[-1]
    widths = ends - starts
    left = np.zeros(len(starts), dtype=np.int64)
    right = np.zeros(len(starts), dtype=np.int64)
    gaps = starts[1:] - ends[:-1]
    right[:-1] = gaps // 2
    left[1:] = gaps - gaps // 2
    eligible = ((widths >= int(params["minimum_width"])) &
                (masses <= float(params["max_packet_mass"]) * total_mass) &
                (left + right >= 2))
    packets = np.flatnonzero(eligible)
    if len(packets) == 0:
        return best_result
    centers = (starts + ends) * 0.5 / n
    cumulative_mass = (prefix[starts] + 0.5*masses) / total_mass
    rng = np.random.default_rng(seed)
    # Whole-comb fission first, followed by coherent regional changes.
    settings = []
    for amount in (0.0625, 0.125, 0.25, 0.5, 0.75, 1.0):
        if time.monotonic() >= deadline:
            break
        for pieces in (2, 3, 4):
            if time.monotonic() >= deadline:
                break
            settings.append((pieces, amount, 0, 0))
    for region in range(1, 7):
        if time.monotonic() >= deadline:
            break
        for amount in (0.125, 0.5, 1.0):
            if time.monotonic() >= deadline:
                break
            for pieces in (2, 3):
                if time.monotonic() >= deadline:
                    break
                settings.append((pieces, amount, region, 0))
    # Smoothly modulated fission tests a chirped rather than uniform finer comb.
    for mode in (1, 2, 3):
        if time.monotonic() >= deadline:
            break
        for amount in (0.25, 0.5, 1.0):
            if time.monotonic() >= deadline:
                break
            settings.append((2, amount, 0, mode))
    trials = 0
    seen = set()
    for pieces, amount, region, mode in settings:
        if time.monotonic() >= deadline or trials >= int(params["trials"]):
            break
        selected = packets
        if region == 1:
            selected = packets[cumulative_mass[packets] >= 0.5]
        elif region == 2:
            selected = packets[cumulative_mass[packets] < 0.5]
        elif region == 3:
            selected = packets[centers[packets] >= 0.75]
        elif region == 4:
            selected = packets[(centers[packets] >= 0.4) & (centers[packets] < 0.75)]
        elif region == 5:
            selected = packets[np.arange(len(packets)) % 2 == 0]
        elif region == 6:
            selected = packets[np.arange(len(packets)) % 2 == 1]
        operations = []
        expired = False
        for j in selected:
            if time.monotonic() >= deadline:
                expired = True
                break
            if widths[j] < pieces:
                continue
            local = amount
            if mode:
                local *= 0.5 + 0.5*np.cos(2*np.pi*mode*centers[j])
            l = int(np.floor(local*left[j] + 0.5))
            r = int(np.floor(local*right[j] + 0.5))
            if l + r:
                operations.append((int(starts[j]), int(ends[j]), pieces, l, r))
        if expired:
            break
        if not operations:
            continue
        signature = tuple(operations)
        if signature in seen:
            continue
        seen.add(signature)
        candidate = f.copy()
        for s, e, k, l, r in operations:
            if time.monotonic() >= deadline:
                expired = True
                break
            candidate[s:e] = 0.0
            count = e - s
            rank = np.arange(count, dtype=np.int64)
            part = rank*k // count
            shift = (part*(l+r) + (k-1)//2)//(k-1) - l
            candidate[s + rank + shift] = f[s:e]
        if expired or time.monotonic() >= deadline:
            break
        trials += 1
        score = exact_score(candidate)
        if np.isfinite(score) and score > best_score:
            best_score = score
            best_result = {
                "base_values": init["values"],
                "fissions": [list(op) for op in operations],
            }
    return best_result
