  "formulation": "Represent a candidate as baseline samples plus disjoint packet-fission operations. Each operation preserves a packet’s ordered values but splits it into several teeth, borrowing bounded space from neighboring zero gaps. The adapter expands this structural representation into the verifier’s dense nonnegative array; canonical candidates remain accepted unchanged.",
  "adapter_source": "import numpy as np


def to_canonical(obj):
    if "values" in obj:
        return obj
    base = np.maximum(np.asarray(obj["base_values"], dtype=np.float64), 0.0)
    out = base.copy()
    for operation in obj.get("fissions", []):
        s, e, k, left, right = map(int, operation)
        if not (0 <= s < e <= len(base) and 2 <= k <= e-s):
            raise ValueError("Invalid packet fission")
        if left < 0 or right < 0:
            raise ValueError("Negative gap allocation")
        rank = np.arange(e-s, dtype=np.int64)
        part = rank*k // (e-s)
        shift = (part*(left+right) + (k-1)//2)//(k-1) - left
        destination = s + rank + shift
        if destination[0] < 0 or destination[-1] >= len(base):
            raise ValueError("Packet outside lattice")
        out[s:e] = 0.0
        out[destination] = base[s:e]
    return {"values": out.tolist()}
